"""Create capstone business, insight, recommendation and dictionary tables."""
from pathlib import Path
import json
import pandas as pd
from scipy import stats
ROOT=Path(__file__).resolve().parents[1];T=ROOT/'outputs/tables';S=ROOT/'outputs/summaries';R=ROOT/'references';R.mkdir(exist_ok=True)
df=pd.read_csv(ROOT/'data/processed/bank_marketing_cleaned.csv');m=json.loads((S/'model_summary.json').read_text());q=json.loads((S/'data_quality.json').read_text())
# problem charter
charter=[('Problem statement','Outbound calls are costly; rank prospects by likelihood of term-deposit subscription before a call, without using post-call information.'),('Primary objective','Build and evaluate a leakage-aware binary classifier that improves subscriber capture per contact.'),('Business user','Campaign manager and marketing analytics team.'),('Prediction unit','One campaign record / client contact record.'),('Prediction timing','Immediately before the outbound call.'),('Target','subscribed = 1 if y = yes; otherwise 0.'),('In scope','Data quality, EDA, feature engineering, chronological validation, classification, ranking lift, error/subgroup analysis, recommendations.'),('Out of scope','Causal campaign uplift, profit optimization, customer lifetime value, real-time deployment, decisions based on call duration.'),('Success criteria','Beat prevalence baseline on ROC-AUC, PR-AUC and top-20% lift; document calibration/drift and subgroup risks.'),('Expected outcome','A reproducible prototype and decision framework, not an autonomous production system.')]
pd.DataFrame(charter,columns=['element','definition']).to_csv(T/'capstone_problem_charter.csv',index=False)
# dictionary
raw_defs={'age':'Client age','job':'Job category','marital':'Marital status','education':'Education category','default':'Credit in default?','housing':'Housing loan?','loan':'Personal loan?','contact':'Contact communication type','month':'Last contact month','day_of_week':'Last contact weekday','duration':'Last call duration in seconds; post-call leakage, excluded from deployable model','campaign':'Contacts during current campaign including current contact','pdays':'Days since previous campaign contact; 999 means not previously contacted','previous':'Contacts before current campaign','poutcome':'Previous campaign outcome','emp_var_rate':'Employment variation rate','cons_price_idx':'Consumer price index','cons_conf_idx':'Consumer confidence index','euribor3m':'Three-month Euribor rate','nr_employed':'Number of employees (quarterly indicator)','subscribed':'Binary target engineered from y'}
eng={'age_band':'Descriptive age band; excluded from model to avoid duplicating age','previously_contacted':'1 when pdays != 999','days_since_previous':'pdays with 999 replaced by missing','contact_pressure':'campaign + previous','has_credit_obligation':'1 if housing or personal loan is yes','unknown_field_count':'Count of categorical fields equal to unknown','source_row':'Original chronological row number'}
rows=[]
for c in df.columns:
 rows.append({'field':c,'dtype':str(df[c].dtype),'role':'Target' if c=='subscribed' else ('Engineered' if c in eng else 'Source feature'),'definition':eng.get(c,raw_defs.get(c,'Source field')),'model_use':'Excluded — target' if c=='subscribed' else ('Excluded — post-call leakage' if c=='duration' else ('Excluded — audit/descriptive' if c in ['source_row','age_band'] else 'Candidate pre-call predictor'))})
pd.DataFrame(rows).to_csv(T/'data_dictionary.csv',index=False)
# stats tests
ct=pd.crosstab(df.poutcome,df.subscribed);chi2,p,dof,exp=stats.chi2_contingency(ct)
rho,pr=stats.spearmanr(df.campaign,df.subscribed)
stats_out={'poutcome_chi_square':chi2,'poutcome_p_value':p,'poutcome_dof':dof,'campaign_contacts_spearman_rho':rho,'campaign_contacts_p_value':pr}
(S/'statistical_tests.json').write_text(json.dumps(stats_out,indent=2))
# insights
ins=[
('Target balance',f"Only {m['overall_positive_rate_pct']:.27g}% of all records subscribe.",f"4,640 positives of {m['raw_rows']:,}",'Accuracy alone is misleading; ranking and PR metrics are required.','Observed'),
('Temporal drift','Subscription prevalence changes sharply across chronological splits.','Train 5.57%; validation 10.65%; test 38.45%','A static model is poorly calibrated across campaign periods; monitoring and retraining are mandatory.','Observed'),
('Model discrimination','The selected histogram gradient boosting model is better than random but modest.','Test ROC-AUC 0.635; PR-AUC 0.513 vs test prevalence 0.385','Useful for prioritisation, not automatic rejection or approval.','Observed'),
('Targeting lift','The top-scored 20% of test records contain 639 subscribers.','26.89% of test subscribers captured; lift 1.35','Ranking can concentrate likely responders when call capacity is limited.','Observed'),
('Threshold trade-off',f"Validation-tuned threshold {m['threshold']:.3f} balances precision and recall.",f"Precision {m['test_tuned_precision']:.3f}; recall {m['test_tuned_recall']:.3f}; F1 {m['test_tuned_f1']:.3f}",'Threshold must be set from campaign economics, not F1 alone.','Observed'),
('Leakage','Using call duration improves apparent scores but violates prediction timing.',f"ROC-AUC rises from {m['test_roc_auc']:.3f} to {m['leakage_roc_auc']:.3f}",'A duration-based pre-call model would be invalid and misleading.','Observed'),
('Previous outcomes','A prior successful campaign is strongly associated with subscription.','Previous-success conversion 65.11%; chi-square p < 0.001','Prior engagement is a useful ranking signal, but not proof of causal persistence.','Observed association'),
('Contact channel','Cellular-contact records convert more often than telephone records.','Cellular 14.74%; telephone 5.23%','Could reflect campaign period/client mix; channel experiments are needed.','Observed association'),
('Contact pressure','More current-campaign contacts are negatively associated with subscription.',f"Spearman rho {rho:.3f}, p < 0.001",'Repeated contacts may signal hard-to-convert prospects or fatigue.','Observed association'),
('Age audit','Precision/recall and selection rates vary across age bands.','Recall ranges from 0.439 to 0.711; older bands have high selection/FPR','Human oversight and subgroup monitoring are needed to prevent unfair targeting.','Observed')]
pd.DataFrame(ins,columns=['business_area','finding','evidence','business_meaning','evidence_type']).to_csv(T/'insights_table.csv',index=False)
# recommendations
recs=[
('Use the model only as a ranked pilot','Top-20% lift is 1.35, but discrimination is modest','High','Run a controlled champion-vs-random pilot on a limited campaign','Subscriber capture per 100 calls; contact cost per subscription','Current offers, contact cost, consent and final outcomes','Temporal drift may erase lift'),
('Monitor temporal drift and recalibrate','Positive rate rises from 5.57% to 38.45% across splits','High','Track prevalence, PR-AUC, calibration and score distribution each campaign; retrain on rolling windows','PR-AUC/prevalence ratio; Brier score; calibration error','Reliable campaign date and outcome timestamps','Historic file lacks an explicit year field per row'),
('Define threshold from campaign economics','F1-optimal threshold is not necessarily profit-optimal','High','Estimate call cost and term-deposit contribution; select threshold under capacity and compliance constraints','Net contribution per contacted client; capacity utilisation','Call cost, product contribution, operational capacity','Economic inputs may change by campaign'),
('Keep duration out of all pre-call scoring','Duration is only known after the call and inflates apparent performance','High','Enforce a prediction-time feature contract and automated leakage tests','Zero post-outcome features in production schema','Feature availability timestamps','Data pipelines may inadvertently reintroduce leakage'),
('Use prior-campaign success carefully','Previous-success conversion is 65.11%','Medium','Create a separate re-engagement strategy, then test against an eligible control group','Incremental subscription rate; opt-out rate','Client key, consent, prior campaign dates and offers','Repeated contact may create fatigue or regulatory risk'),
('Test contact policy rather than infer causality','Cellular channel and lower contact counts correlate with conversion','Medium','Randomise channel/time/contact cadence for eligible clients','Incremental conversion; complaints; cost per subscription','Consent, channel eligibility, timestamps, complaints','Operational constraints and selection bias'),
('Implement responsible-model controls','Age-band selection and false-positive rates vary','High','Review age-related use, monitor subgroup metrics, provide human override and adverse-impact review','Selection, precision, recall and FPR by approved groups','Governance policy and legally permitted attributes','Fairness definitions and legal requirements vary'),
('Improve the data layer','No client ID, offer value, cost or explicit date/year per row','Long term','Capture anonymised client key, campaign timestamp, offer, cost, consent and outcome','Data completeness; reproducible time split; campaign ROI','New governed campaign fact table','Privacy, consent and integration work')]
pd.DataFrame(recs,columns=['recommendation','supporting_finding','priority','implementation_steps','success_kpi','data_needed','challenge']).to_csv(T/'recommendation_matrix.csv',index=False)
# errors/limitations
lims=[('Temporal distribution shift','Test prevalence is 38.45% vs 5.57% train','Calibration and threshold stability are weak','Rolling validation, campaign dates, recalibration'),('False negatives',f"Tuned test model misses {1050:,} of {m['test_subscribers']:,} subscribers",'Lost campaign opportunities','Adjust threshold based on capacity/cost; improve features'),('False positives','Tuned model selects 1,283 non-subscribers','Wasted calls and customer fatigue','Use economics, consent and suppression rules'),('Feature leakage','Duration known only after call','Inflated offline scores','Prediction-time feature contract'),('Repeated clients possible','UCI notes multiple contacts may occur; no client ID','Rows may not be independent','Add anonymised client key and grouped split'),('Historic geography/time','Portuguese campaigns, 2008–2010','Limited current and geographic validity','Collect current local campaign data'),('No causal design','Observational campaign data','Associations do not prove interventions work','Randomised or quasi-experimental tests'),('Fairness scope','Only age available for subgroup audit','Incomplete fairness assessment','Legal review and approved group monitoring')]
pd.DataFrame(lims,columns=['issue','evidence','impact','improvement']).to_csv(T/'error_limitations.csv',index=False)
print('documentation complete')
